export function getDriftErrorMessage(code: DriftError): string {
  if (process.env["NODE_ENV"] !== "production") {
    return (driftErrorMessages as Record<DriftError, string>)[code];
  }

  return "Error message not available in production bundles.";
}

export function isDriftError<TProgramErrorCode extends DriftError>(
  error: unknown,
  transactionMessage: { instructions: Record<number, { programAddress: Address }> },
  code?: TProgramErrorCode
): error is SolanaError<typeof SOLANA_ERROR__INSTRUCTION_ERROR__CUSTOM> &
  Readonly<{ context: Readonly<{ code: TProgramErrorCode }> }> {
  return isProgramError<TProgramErrorCode>(error, transactionMessage, DRIFT_PROGRAM_ADDRESS, code);
}
